function SettingsEditor({ title, fields, setFields, company = false, onSave, loading }) {  const update = (field, value) => setFields((current) => ({ ...current, [field]: value }));  return <div className="rounded-2xl border border-[#e9e9ef] bg-white p-5 sm:p-7"><div className="flex items-center justify-between"><div><h3 className="text-sm font-extrabold">{title}</h3><p className="mt-1 text-xs leading-5 text-[#92939d]">Changes save directly to your workspace.</p></div><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#f0efff] text-[#6957f5]">{company ? <Building2 size={17} /> : <Store size={17} />}</div></div><div className="mt-7 space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label={company ? "Company name" : "Store name"} value={fields.name} onChange={(event) => update("name", event.target.value)} /><Field label={company ? "Country" : "Phone"} value={company ? fields.country : fields.phone} onChange={(event) => update(company ? "country" : "phone", event.target.value)} /></div><Field label="Address" value={fields.address} onChange={(event) => update("address", event.target.value)} />{company && <><div className="grid gap-4 sm:grid-cols-2"><Field label="Business email" type="email" value={fields.email || ""} onChange={(event) => update("email", event.target.value)} /><Field label="Phone" value={fields.phone || ""} onChange={(event) => update("phone", event.target.value)} /></div><Field label="Tax ID (GDT)" value={fields.tax_id || ""} onChange={(event) => update("tax_id", event.target.value)} placeholder="e.g. 000 123 456 789" /></>}{!company && <><label className="block"><span className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Timezone</span><Dropdown value={fields.timezone} onChange={(v) => update("timezone", v)} options={[{ value: "Asia/Phnom_Penh", label: "Asia/Phnom_Penh" }, { value: "Asia/Bangkok", label: "Asia/Bangkok" }, { value: "Asia/Singapore", label: "Asia/Singapore" }]} /></label><label className="block"><span className="mb-1.5 block text-xs font-semibold text-[#4f5059]">Service tax (%)</span><input type="number" min="0" max="100" step="0.01" value={fields.service_tax_rate} onChange={(event) => update("service_tax_rate", event.target.value)} className="h-11 w-full rounded-xl border border-[#dfdfe8] bg-white px-3.5 text-sm outline-none focus:border-[#887bf3]" /></label></>}</div><div className="mt-8 flex justify-end border-t border-[#eeeeF2] pt-5"><Button onClick={onSave} disabled={loading}>{loading ? "Saving..." : "Save changes"} <Check size={14} /></Button></div></div>;}

