function ReceiptSheetBody({ order, workspace }) {  const prefs = workspace?.store?.preferences || {};const size = prefs.receipt_size === "a4" ? "a4" : prefs.receipt_size === "a5" ? "a5" : "thermal";  const template = size === "thermal" ? "classic" : prefs.receipt_template === "professional" ? "professional" : "classic";  return template === "professional" ? <ReceiptProfessionalBody order={order} workspace={workspace} /> : <ReceiptClassicBody order={order} workspace={workspace} />;}

function ReceiptLiveSheet({ workspace, draft }) {  const prefs = draft || {};const size = prefs.receipt_size === "a4" ? "a4" : prefs.receipt_size === "a5" ? "a5" : "thermal";  const template = size === "thermal" ? "classic" : prefs.receipt_template === "professional" ? "professional" : "classic";  const mmW = size === "thermal" ? 80 : size === "a5" ? 148 : 210;  const mmH = size === "thermal" ? null : size === "a5" ? 210 : 297;  const width = Math.round(mmW * 3.779527559055118);  const minHeight = mmH ? Math.round(mmH * 3.779527559055118) : null;  const pw = { ...workspace, store: { ...(workspace?.store || {}), preferences: { ...(workspace?.store?.preferences || {}), ...prefs } } };const order = buildReceiptDemo(workspace, prefs);  const [holder, setHolder] = useState(null);  const [sheet, setSheet] = useState(null);  const [scale, setScale] = useState(1);  const [contentH, setContentH] = useState(minHeight || 600);  useEffect(() => {    if (!holder) return;    const fit = () => setScale(Math.min(1, Math.max(0.25, (holder.clientWidth - 8) / width)));    fit();    if (typeof ResizeObserver !== "undefined") { const ro = new ResizeObserver(fit); ro.observe(holder); return () => ro.disconnect(); }  }, [holder, width]);  useEffect(() => {    if (!sheet) return;    const raf = requestAnimationFrame(() => setContentH((current) => { const next = minHeight || sheet.scrollHeight; return Math.abs(current - next) > 2 ? next : current; }));    return () => cancelAnimationFrame(raf);  }, [sheet, minHeight, prefs, template, size]);  const displayW = Math.round(width * scale);  const displayH = Math.round(contentH * scale);  const label = { thermal: "Thermal 80mm", a5: "A5 · 148 × 210 mm", a4: "A4 · 210 × 297 mm" }[size];  return (    <div className="mt-7 rounded-2xl border border-[#e9e9ef] bg-white p-4 sm:p-6">      <div className="flex flex-wrap items-center justify-between gap-3">        <div><h4 className="text-sm font-extrabold">Live receipt preview</h4><p className="mt-1 text-[11px] text-[#999aa4]">True paper size. Updates instantly as you change settings.</p></div>        <Badge tone="violet">{label} · {template === "professional" ? "Professional" : "Classic"}</Badge>      </div>      <div ref={setHolder} className="app-scrollbar mt-4 overflow-x-auto rounded-xl border border-[#ececf1] bg-[#eef0f4] px-5 py-6">        <div className="mx-auto bg-white shadow-[0_6px_24px_rgba(20,21,28,.08)]" style={{ width: displayW, height: displayH }}>          <div style={{ width, minHeight, transform: `scale(${scale})`, transformOrigin: "top left" }} ref={setSheet}>            <ReceiptSheetBody order={order} workspace={pw} />          </div>        </div>      </div>    </div>  );}

